/* Chip = a Button with a selectable (toggle) state, always pill-shaped.
 * Sizing and colors are IDENTICAL to .btn so chips and buttons match 1:1;
 * only [data-selected] (pick-one / multi-select groups) is chip-specific. */
.chip {
  /* Sizes to its label, never to its container. `display: inline-flex` is not
     enough: as a flex or grid child with the default `stretch`, the cross size
     is set by the parent and the pill runs the full width — a badge that reads
     as a text input, which is exactly how it shipped on the patterns screen
     (measured 2026-08-22: 219px of pill around 48px of text). An explicit
     inline-size opts out of stretch, in both axes' worth of cases. */
  inline-size: fit-content;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);   /* icon↔label */
  height: var(--control-height);
  padding-inline: var(--control-padding-x);
  border-radius: var(--radius-full);   /* always pill */
  border: none;
  font-family: inherit;
  font-weight: var(--control-font-weight);
  font-size: var(--control-font-size);
  /* --surface-contrast, not --secondary. --secondary IS --muted (both
   * neutral-100), so on the page surface the pill was painting itself the
   * colour of the page and there was no pill — just a word floating in a row of
   * controls that all had shapes. Same one-line rule the secondary button
   * follows: on grey go white, on white go grey. */
  background: var(--surface-contrast);
  color: var(--secondary-foreground);
  cursor: pointer;
  transition: background var(--duration-fast), color var(--duration-fast);
}
.chip:hover { background: var(--surface-contrast-hover); }
/* Pressed — one stop past hover. */
.chip:active { background: var(--surface-contrast-active); }
.chip:focus-visible { outline: var(--ring-width) solid var(--ring); outline-offset: var(--ring-offset); }
.chip:disabled { opacity: 0.5; cursor: not-allowed; pointer-events: none; }

/* ── Sizes — mirror .btn ───── */
.chip[data-size="sm"] { height: var(--control-height-sm); padding-inline: var(--space-3); font-size: var(--font-sm); }
.chip[data-size="lg"] { height: var(--control-height-lg); font-size: var(--control-font-size-lg); }

/* ── Variants — identical colors to .btn ───── */
.chip[data-variant="primary"] { background: var(--primary); color: var(--primary-foreground); }
.chip[data-variant="primary"]:hover { background: var(--primary-hover); }
.chip[data-variant="primary"]:active { background: var(--primary-active); }

.chip[data-variant="ghost"] { background: transparent; color: var(--foreground); }
.chip[data-variant="ghost"]:hover { background: var(--accent-soft); }
.chip[data-variant="ghost"]:active { background: var(--accent); }

.chip[data-variant="destructive"] { background: var(--destructive); color: var(--destructive-foreground); }

.chip[data-variant="dark"] { background: var(--secondary-foreground); color: var(--background); }
.chip[data-variant="dark"]:hover { background: var(--foreground); }

/* ── Selected — primary fill, overrides the variant (pick-one / toggle groups).
 * Placed last so it wins over variant rules at equal specificity. ───── */
.chip[data-selected] { background: var(--primary); color: var(--primary-foreground); }
.chip[data-selected]:hover { background: var(--primary-hover); }
.chip[data-selected]:active { background: var(--primary-active); }

import './Chip.css'
import { type ButtonHTMLAttributes, type Ref } from 'react'
import { cn } from '../lib/cn'
import { Icon, type IconName } from '../Icon'

/** Same variants as Button. Default is `secondary` (subtle) since chips are
 *  usually shown in groups; pass `selected` for the toggled/active state. */
type Variant = 'secondary' | 'primary' | 'ghost' | 'destructive' | 'dark'
type Size = 'sm' | 'md' | 'lg'

type Props = ButtonHTMLAttributes<HTMLButtonElement> & {
  /** Forwarded to the underlying <button>. */
  ref?: Ref<HTMLButtonElement>
  variant?: Variant
  size?: Size
  /** Toggled/active state for pick-one or multi-select chip groups (primary fill). */
  selected?: boolean
  /** Optional leading icon. */
  icon?: IconName
}

/* Rounded selectable label. A Button with a toggle state, always pill-shaped:
 * quick actions, quick replies, pick-a-reason chips, filters, etc. 
   *
   * Copy: names the filter it applies, not the act of filtering — "Overdue", not
   * "Filter by overdue".
   */
export function Chip({ variant = 'secondary', size = 'md', selected, icon, className, type = 'button', children, ref, ...rest }: Props) {
  return (
    <button
      ref={ref}
      type={type}
      className={cn('chip', className)}
      data-variant={variant}
      data-size={size}
      data-selected={selected || undefined}
      aria-pressed={selected}
      {...rest}
    >
      {icon && <Icon name={icon} />}
      {children}
    </button>
  )
}
